import Foundation

extension Scheme.Scrolling {
    struct Modifiers: Equatable, Codable, ImplicitInitable {
        var command: Action?
        var shift: Action?
        var option: Action?
        var control: Action?
    }
}

extension Scheme.Scrolling.Modifiers {
    enum Action: Equatable {
        case auto
        case ignore
        case preventDefault
        case alterOrientation
        case changeSpeed(scale: Decimal)
        case zoom
        case zoomReversed
        case pinchZoom
        case pinchZoomReversed
    }
}

extension Scheme.Scrolling.Modifiers {
    func merge(into modifiers: inout Self) {
        if let command {
            modifiers.command = command
        }

        if let shift {
            modifiers.shift = shift
        }

        if let option {
            modifiers.option = option
        }

        if let control {
            modifiers.control = control
        }
    }

    func merge(into modifiers: inout Self?) {
        if modifiers == nil {
            modifiers = Self()
        }

        merge(into: &modifiers!)
    }
}

extension Scheme.Scrolling.Modifiers.Action: Codable {
    enum CodingKeys: String, CodingKey {
        case type, scale
    }

    enum ActionType: String, Codable {
        @available(*, deprecated)
        case none
        case auto
        case ignore
        case preventDefault
        case alterOrientation
        case changeSpeed
        case zoom
        case zoomReversed
        case pinchZoom
        case pinchZoomReversed
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let type = try container.decode(ActionType.self, forKey: .type)

        switch type {
        case .none, .auto:
            self = .auto
        case .ignore:
            self = .ignore
        case .preventDefault:
            self = .preventDefault
        case .alterOrientation:
            self = .alterOrientation
        case .changeSpeed:
            let scale = try container.decode(Decimal.self, forKey: .scale)
            self = .changeSpeed(scale: scale)
        case .zoom:
            self = .zoom
        case .zoomReversed:
            self = .zoomReversed
        case .pinchZoom:
            self = .pinchZoom
        case .pinchZoomReversed:
            self = .pinchZoomReversed
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)

        switch self {
        case .auto:
            try container.encode(ActionType.auto, forKey: .type)
        case .ignore:
            try container.encode(ActionType.ignore, forKey: .type)
        case .preventDefault:
            try container.encode(ActionType.preventDefault, forKey: .type)
        case .alterOrientation:
            try container.encode(ActionType.alterOrientation, forKey: .type)
        case let .changeSpeed(scale):
            try container.encode(ActionType.changeSpeed, forKey: .type)
            try container.encode(scale, forKey: .scale)
        case .zoom:
            try container.encode(ActionType.zoom, forKey: .type)
        case .zoomReversed:
            try container.encode(ActionType.zoomReversed, forKey: .type)
        case .pinchZoom:
            try container.encode(ActionType.pinchZoom, forKey: .type)
        case .pinchZoomReversed:
            try container.encode(ActionType.pinchZoomReversed, forKey: .type)
        }
    }
}

