import Foundation

extension Scheme {
    struct Scrolling: Codable, Equatable, ImplicitInitable {
        @ImplicitOptional var reverse: Bidirectional
        @ImplicitOptional var distance: Bidirectional
        @ImplicitOptional var acceleration: Bidirectional
        @ImplicitOptional var speed: Bidirectional
        @ImplicitOptional var smoothed: Bidirectional
        @ImplicitOptional var modifiers: Bidirectional

        init() {}

        init(
            reverse: Bidirectional? = nil,
            distance: Bidirectional? = nil,
            acceleration: Bidirectional? = nil,
            speed: Bidirectional? = nil,
            smoothed: Bidirectional? = nil,
            modifiers: Bidirectional? = nil
        ) {
            $reverse = reverse
            $distance = distance
            $acceleration = acceleration
            $speed = speed
            $smoothed = smoothed
            $modifiers = modifiers
        }
    }
}

extension Scheme.Scrolling {
    func merge(into scrolling: inout Self) {
        $reverse?.merge(into: &scrolling.reverse)
        $distance?.merge(into: &scrolling.distance)
        $acceleration?.merge(into: &scrolling.acceleration)
        $speed?.merge(into: &scrolling.speed)
        merge(smoothed: $smoothed, into: &scrolling.smoothed)
        $modifiers?.merge(into: &scrolling.modifiers)
    }

    func merge(into scrolling: inout Self?) {
        if scrolling == nil {
            scrolling = Self()
        }

        merge(into: &scrolling!)
    }

    private func merge(smoothed source: Bidirectional?, into target: inout Bidirectional) {
        guard let source else {
            return
        }

        var merged = target

        if let sourceVertical = source.vertical {
            if merged.vertical == nil {
                merged.vertical = sourceVertical
            } else {
                sourceVertical.merge(into: &merged.vertical!)
            }
        }

        if let sourceHorizontal = source.horizontal {
            if merged.horizontal == nil {
                merged.horizontal = sourceHorizontal
            } else {
                sourceHorizontal.merge(into: &merged.horizontal!)
            }
        }

        target = merged
    }
}

