                        value: $state.scrollingDistanceInPixels,
                        in: 0 ... 128
                    ) {
                        Text("Distance")
                    } minimumValueLabel: {
                        Text(verbatim: "0px")
                    } maximumValueLabel: {
                        Text(verbatim: "128px")
                    }
                }
            }
            .modifier(SectionViewModifier())
        }
    }
}

