                } else {
                    Text(text)
                }
            }
            .padding(.horizontal, 10)
            .frame(maxWidth: .infinity, minHeight: 30, maxHeight: 30, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .background(Color.accentColor.opacity(isActive ? 1 : 0))
        .cornerRadius(5)
        .foregroundColor(isActive ? .white : .primary)
    }
}

